-- Instalación aditiva: no sobrescribe ajustes existentes.

MERGE INTO FERIADOS destino
USING (SELECT 'ANIO_NUEVO' CODIGO, 'Año Nuevo' NOMBRE, DATE '2026-01-01' FECHA, DATE '2026-01-01' FECHA_CONMEMORACION, 'NACIONAL' AMBITO, '*' LOCALIDAD, 0 MINUTO_INICIO, 1440 MINUTO_FIN, 'Código de Trabajo art. 127; AGN calendario 2026; Día del Ejército trasladado conforme Decreto 42-2010 reformado por 19-2018' FUNDAMENTO FROM DUAL) origen
ON (NVL(destino.CODIGO_ANTERIOR,destino.CODIGO) = origen.CODIGO AND destino.FECHA_CONMEMORACION = origen.FECHA_CONMEMORACION AND destino.LOCALIDAD = origen.LOCALIDAD)
WHEN NOT MATCHED THEN INSERT (CODIGO, NOMBRE, FECHA, FECHA_CONMEMORACION, AMBITO, LOCALIDAD, MINUTO_INICIO, MINUTO_FIN, FUNDAMENTO)
VALUES (origen.CODIGO, origen.NOMBRE, origen.FECHA, origen.FECHA_CONMEMORACION, origen.AMBITO, origen.LOCALIDAD, origen.MINUTO_INICIO, origen.MINUTO_FIN, origen.FUNDAMENTO);
/

